                maxConcurrency: 1,
                memoryNamespace: 'voice_agent',
                tier: 'local'
            },

            // Ã¢â€¢ÂÃ¢â€¢ÂÃ¢â€¢Â WORKER 6: Vector Maestro Ã¢â€¢ÂÃ¢â€¢ÂÃ¢â€¢Â
            {
                id: config.embeddingModel,
                configKey: 'embeddingModel',
                role: 'Vector Maestro Ã¢â‚¬â€ high-density embedding generation',
