603	        // HF Router API: model goes in the request body, NOT the URL path
604	        const modelPath = params.model.replace('huggingface:', '');
605	        const url = `https://router.huggingface.co/v1/chat/completions`;
606	
607	        const messages: Array<{ role: string; content: string }> = [];
