609	        if (params.systemPrompt) {
610	            messages.push({ role: 'system', content: params.systemPrompt });
611	        }
612	
613	        messages.push({ role: 'user', content: params.prompt });
614	
615	        const body = {
616	            model: modelPath,
617	            messages,
618	            max_tokens: params.maxTokens ?? 4096,
619	            temperature: params.temperature ?? 0.7,
620	            stream: false
621	        };
622	
623	        try {
624	            const response = await undiciFetch(url, {
