641	                choices?: Array<{
642	                    message?: { content?: string };
643	                    finish_reason?: string;
644	                }>;
645	                usage?: { total_tokens?: number };
646	            };
647	
648	            const text = data.choices?.[0]?.message?.content ?? '';
