650	
651	            logger.debug({ model: params.model, latency, tokens: data.usage?.total_tokens }, 'Primary Cloud call complete');
652	
653	            return {
654	                ok: true,
655	                value: {
656	                    response: text,
657	                    model: params.model,
658	                    latency,
659	                    tokensUsed: data.usage?.total_tokens
660	                }
661	            };
662	        } catch (err) {
