1097	    private async embedGemini(text: string): Promise<Result<Float32Array>> {
1098	        const apiKey = this.config.secondaryCloudApiKey;
1099	        if (!apiKey) return { ok: false, error: new Error('SECONDARY_CLOUD_API_KEY not set') };
1100	
1101	        // Tiered Embedding Fallback Sequence
1102	        const primaryModel = this.config.geminiEmbeddingModel;
1103	        const fallbackSequence = [
1104	            primaryModel,
1105	            'text-embedding-004',
1106	            'models/text-embedding-004',
1107	            'gemini-embedding-001',
1108	            'models/embedding-001'
1109	        ];
1110	
1111	        const uniqueSequence = Array.from(new Set(fallbackSequence));
1112	        let lastError: Error | undefined;
1113	
1114	        for (const modelId of uniqueSequence) {
1115	            const url = `https://generativelanguage.googleapis.com/v1beta/models/${modelId}:embedContent?key=${apiKey}`;
1116	
1117	            try {
1118	                const response = await undiciFetch(url, {
1119	                    method: 'POST',
1120	                    headers: { 'Content-Type': 'application/json' },
1121	                    body: JSON.stringify({ content: { parts: [{ text }] } }),
1122	                    signal: AbortSignal.timeout(this.getTimeoutByYaoState())
1123	                });
1124	
1125	                if (!response.ok) {
1126	                    const errorText = await response.text();
1127	                    if (response.status === 404) {
1128	                        logger.warn({ modelId }, 'Gemini embedding model not found (404), trying next...');
1129	                        lastError = new Error(`Gemini embed 404: ${modelId} - ${errorText}`);
1130	                        continue;
1131	                    }
1132	                    return { ok: false, error: new Error(`Gemini embed error ${response.status}: ${errorText}`) };
1133	                }
1134	
1135	                const data = await response.json() as { embedding?: { values?: number[] } };
1136	                const values = data.embedding?.values ?? [];
1137	                if (values.length === 0) {
1138	                    lastError = new Error(`Gemini embed ${modelId} returned empty values.`);
1139	                    continue;
1140	                }
1141	
1142	                logger.debug({ modelId }, 'Gemini embedding complete');
1143	                return { ok: true, value: new Float32Array(values) };
1144	            } catch (err) {
1145	                logger.error({ err, modelId }, 'Gemini embedding network failure');
1146	                lastError = err as Error;
1147	            }
1148	        }
1149	
