702	        }, 'Ã°Å¸Å½Â¯ Identifying priority production target.');
703	
704	        return this.run({ ...best.checkpoint.request, ...requestDefaults });
705	    }
706	
707	    /**
708	     * runBatch - Iterates through the entire Gutenberg library using orchestrator logic.
709	     */
710	    public async runBatch(request: Omit<PipelineRequest, 'bookId'>): Promise<Result<void>> {
711	        logger.info('Ã°Å¸Å¡â‚¬ Global Cinema Batch triggered via Sovereign Orchestration.');
712	
713	        // 1. First, finish everything already in progress
714	        let orchestrateRes = await this.orchestrate(request);
715	        while (orchestrateRes.ok && (orchestrateRes.value as any)?.manifest) {
716	            orchestrateRes = await this.orchestrate(request);
717	        }
718	
719	        // 2. Then, ingest new books from library
720	        const library = this.gutenberg.getLibrary();
721	        for (const book of library) {
722	            const storageRes = this.gutenberg.getBookStorageInfo(book.id);
723	            if (storageRes.ok) {
724	                const manifestPath = join(this.basePath, storageRes.value.category, storageRes.value.folderName, '1-storyboard', 'manifest.json');
725	                if (existsSync(manifestPath)) {
726	                    const manifest = JSON.parse(readFileSync(manifestPath, 'utf8')) as PipelineManifest;
727	                    if (manifest.status === 'complete') continue;
728	                }
729	            }
730	
731	            logger.info({ bookId: book.id, title: book.title }, 'Ingesting next volume in batch...');
732	            await this.run({ ...request, bookId: book.id });
733	        }
734	
735	        return ok(undefined);
736	    }
737	
738	    private saveCheckpoint(bookId: number, request: PipelineRequest, manifest: PipelineManifest, stage: 'storyboard' | 'images' | 'voice' | 'assembly', sceneIndex: number, stage1Path: string, error?: string) {
739	        const checkpointPath = join(stage1Path, `checkpoint.json`);
740	        const manifestPath = join(stage1Path, `manifest.json`);
741	
742	        // Audit for corruptions to store in checkpoint
743	        const audit = this.verifyWork(manifest);
744	        const corruptArtifacts = !audit.ok ? [audit.error?.message || 'Unknown error'] : [];
745	
746	        const checkpoint: PipelineCheckpoint = {
747	            request, manifest, lastCompletedStage: stage, lastSceneIndex: sceneIndex,
748	            timestamp: Date.now(), version: '1.2.1-integrity',
749	            lastError: error,
750	            corruptArtifacts
751	        };
752	        writeFileSync(checkpointPath, JSON.stringify(checkpoint, null, 2));
753	        writeFileSync(manifestPath, JSON.stringify(manifest, null, 2));
754	    }
755	
756	    /**
757	     * verifyWork - Audits the pipeline output for empty files, 0-byte assets, or missing scenes.
758	     */
759	    public verifyWork(manifest: PipelineManifest): Result<void> {
760	        const corrupt: string[] = [];
761	
762	        for (const artifact of manifest.scenes) {
763	            // Check Images
764	            for (const img of artifact.imagePaths) {
765	                if (!existsSync(img)) {
766	                    corrupt.push(`Scene ${artifact.index}: Project missing image substrate ${basename(img)}`);
767	                } else if (statSync(img).size < 100) { // Tiny file threshold
768	                    corrupt.push(`Scene ${artifact.index}: Corrupt/Empty image ${basename(img)}`);
769	                }
770	            }
771	
772	            // Check Voice
773	            if (artifact.voiceStatus === 'success' && artifact.voicePath) {
774	                if (!existsSync(artifact.voicePath)) {
775	                    corrupt.push(`Scene ${artifact.index}: Missing narration ${artifact.index}.wav`);
776	                } else if (statSync(artifact.voicePath).size < 1000) { // Narration is usually > 1KB
777	                    corrupt.push(`Scene ${artifact.index}: Narration too short/silent`);
778	                }
779	            }
780	        }
781	
782	        // Check for duplicates
783	        const seenIndices = new Set<number>();
784	        for (const scene of manifest.scenes) {
785	            if (seenIndices.has(scene.index)) {
786	                corrupt.push(`Duplicate scene index detected: ${scene.index}`);
787	            }
788	            seenIndices.add(scene.index);
789	        }
790	
791	        if (corrupt.length > 0) {
792	            return { ok: false, error: new Error(corrupt.join(' | ')) };
793	        }
794	
795	        return ok(undefined);
796	    }
797	
798	    private async withRetry<T>(fn: () => Promise<Result<T>>, maxRetries: number): Promise<Result<T>> {
799	        let lastError: Error | undefined;
800	        for (let attempt = 0; attempt <= maxRetries; attempt++) {
801	            const result = await fn();
802	            if (result.ok) return result;
803	            lastError = result.error;
804	            if (attempt < maxRetries) {
805	                const delayMs = Math.pow(2, attempt) * 1000;
806	                logger.warn({ attempt: attempt + 1, delayMs }, `Retry in ${delayMs}ms...`);
807	                await new Promise(resolve => setTimeout(resolve, delayMs));
808	            }
809	        }
810	        return { ok: false, error: lastError || new Error('Max retries exceeded') };
811	    }
812	
813	    public healthCheck(): { online: boolean; details: string } {
814	        return {
815	            online: existsSync(this.basePath),
816	            details: existsSync(this.basePath) ? 'Pipeline substrate verified.' : 'Pipeline output path missing.'
817	        };
818	    }
819	}
