                    bookId,
                    pipelinePath,
                    scenes: {
                        totalExpected: scenes.length,
                        imagesVerified: manifest.successfulImages,
                        voiceVerified: manifest.successfulVoice
                    },
                    video: manifest.videoPath ? { verified: true, path: manifest.videoPath } : { verified: false, skipped: skipVideo }
                };

                return ok({ manifest, output: JSON.stringify(summaryJson, null, 2) });
            },
            3600_000 // 1 hour timeout for full production
        );
    }

    /**
     * orchestrate - The Sovereign Orchestrator.
     * Scans the tiered library for incomplete pipelines, calculates progress metrics,
     * and resumes the "most finished" book to ensure sequential integrity.
     */
    public async orchestrate(requestDefaults: Partial<PipelineRequest> = {}): Promise<Result<PipelineResult | void>> {
        logger.info('Ã°Å¸Â§Â¬ Neuro-Scanning tiered storage for active production manifests...');

        const candidates: { manifest: PipelineManifest, checkpoint: PipelineCheckpoint, progress: number }[] = [];
        const categories = readdirSync(this.basePath);

        for (const cat of categories) {
            const catPath = join(this.basePath, cat);
            if (!statSync(catPath).isDirectory()) continue;

            const books = readdirSync(catPath);
            for (const bookDir of books) {
                const bookPath = join(catPath, bookDir);
                if (!statSync(bookPath).isDirectory()) continue;

                const stage1Path = join(bookPath, '1-storyboard');
                const rootManifestPath = join(bookPath, 'manifest.json');
                const tieredManifestPath = join(stage1Path, 'manifest.json');
                const checkpointPath = join(stage1Path, 'checkpoint.json');

                let manifestPath = existsSync(tieredManifestPath) ? tieredManifestPath : (existsSync(rootManifestPath) ? rootManifestPath : null);

                if (manifestPath) {
                    try {
                        // Migration: Move manifest to 1-storyboard if it's in the root
                        if (manifestPath === rootManifestPath) {
                            if (!existsSync(stage1Path)) mkdirSync(stage1Path, { recursive: true });
                            renameSync(rootManifestPath, tieredManifestPath);
                            manifestPath = tieredManifestPath;
                            logger.info({ book: bookDir }, 'Migrated manifest to 1-storyboard.');
                        }

                        const manifest = JSON.parse(readFileSync(manifestPath, 'utf8')) as PipelineManifest;

                        if (manifest.status !== 'complete') {
                            const progress = (manifest.successfulImages + manifest.successfulVoice) / (manifest.totalScenes * 2);

                            // Reconstruct or load checkpoint
                            let checkpoint: PipelineCheckpoint | null = null;
                            if (existsSync(checkpointPath)) {
                                checkpoint = JSON.parse(readFileSync(checkpointPath, 'utf8')) as PipelineCheckpoint;
                            } else {
                                // Neuro-Reconstruction: Create a basic checkpoint if missing
                                checkpoint = {
                                    request: { bookId: manifest.bookId, sceneCount: manifest.totalScenes },
                                    manifest,
                                    lastCompletedStage: 'voice', // Assume finishing audio is next
                                    lastSceneIndex: manifest.scenes.length,
                                    timestamp: Date.now(),
                                    version: '1.2.1-reconstructed'
                                };
                            }
                            candidates.push({ manifest, checkpoint, progress });
                        }
                    } catch (e) {
                        logger.warn({ bookDir }, 'Failed to parse volume for orchestration.');
                    }
                }
            }
        }

        if (candidates.length === 0) {
            logger.info('Ã¢Å“Â¨ All current production volumes are complete. Scanning catalog for fresh ingestion...');
            return ok(undefined);
        }

        // Sort by progress descending (Highest progress first)
        candidates.sort((a, b) => b.progress - a.progress);
        const best = candidates[0];

        logger.info({
            book: best.manifest.bookTitle,
            progress: (best.progress * 100).toFixed(1) + '%',
            id: best.manifest.bookId
        }, 'Ã°Å¸Å½Â¯ Identifying priority production target.');

        return this.run({ ...best.checkpoint.request, ...requestDefaults });
    }

    /**
     * runBatch - Iterates through the entire Gutenberg library using orchestrator logic.
     */
    public async runBatch(request: Omit<PipelineRequest, 'bookId'>): Promise<Result<void>> {
        logger.info('Ã°Å¸Å¡â‚¬ Global Cinema Batch triggered via Sovereign Orchestration.');

        // 1. First, finish everything already in progress
        let orchestrateRes = await this.orchestrate(request);
        while (orchestrateRes.ok && (orchestrateRes.value as any)?.manifest) {
            orchestrateRes = await this.orchestrate(request);
        }

        // 2. Then, ingest new books from library
        const library = this.gutenberg.getLibrary();
        for (const book of library) {
            const storageRes = this.gutenberg.getBookStorageInfo(book.id);
            if (storageRes.ok) {
                const manifestPath = join(this.basePath, storageRes.value.category, storageRes.value.folderName, '1-storyboard', 'manifest.json');
                if (existsSync(manifestPath)) {
                    const manifest = JSON.parse(readFileSync(manifestPath, 'utf8')) as PipelineManifest;
                    if (manifest.status === 'complete') continue;
                }
            }

            logger.info({ bookId: book.id, title: book.title }, 'Ingesting next volume in batch...');
            await this.run({ ...request, bookId: book.id });
        }

        return ok(undefined);
    }

    private saveCheckpoint(bookId: number, request: PipelineRequest, manifest: PipelineManifest, stage: 'storyboard' | 'images' | 'voice' | 'assembly', sceneIndex: number, stage1Path: string, error?: string) {
        const checkpointPath = join(stage1Path, `checkpoint.json`);
        const manifestPath = join(stage1Path, `manifest.json`);

        // Audit for corruptions to store in checkpoint
        const audit = this.verifyWork(manifest);
        const corruptArtifacts = !audit.ok ? [audit.error?.message || 'Unknown error'] : [];

        const checkpoint: PipelineCheckpoint = {
            request, manifest, lastCompletedStage: stage, lastSceneIndex: sceneIndex,
            timestamp: Date.now(), version: '1.2.1-integrity',
            lastError: error,
            corruptArtifacts
        };
        writeFileSync(checkpointPath, JSON.stringify(checkpoint, null, 2));
        writeFileSync(manifestPath, JSON.stringify(manifest, null, 2));
    }

    /**
     * verifyWork - Audits the pipeline output for empty files, 0-byte assets, or missing scenes.
     */
    public verifyWork(manifest: PipelineManifest): Result<void> {
        const corrupt: string[] = [];

        for (const artifact of manifest.scenes) {
            // Check Images
            for (const img of artifact.imagePaths) {
                if (!existsSync(img)) {
                    corrupt.push(`Scene ${artifact.index}: Project missing image substrate ${basename(img)}`);
                } else if (statSync(img).size < 100) { // Tiny file threshold
                    corrupt.push(`Scene ${artifact.index}: Corrupt/Empty image ${basename(img)}`);
                }
            }

            // Check Voice
            if (artifact.voiceStatus === 'success' && artifact.voicePath) {
                if (!existsSync(artifact.voicePath)) {
                    corrupt.push(`Scene ${artifact.index}: Missing narration ${artifact.index}.wav`);
                } else if (statSync(artifact.voicePath).size < 1000) { // Narration is usually > 1KB
                    corrupt.push(`Scene ${artifact.index}: Narration too short/silent`);
                }
            }
        }

        // Check for duplicates
        const seenIndices = new Set<number>();
        for (const scene of manifest.scenes) {
            if (seenIndices.has(scene.index)) {
                corrupt.push(`Duplicate scene index detected: ${scene.index}`);
            }
            seenIndices.add(scene.index);
        }

        if (corrupt.length > 0) {
            return { ok: false, error: new Error(corrupt.join(' | ')) };
        }

        return ok(undefined);
    }

    private async withRetry<T>(fn: () => Promise<Result<T>>, maxRetries: number): Promise<Result<T>> {
        let lastError: Error | undefined;
        for (let attempt = 0; attempt <= maxRetries; attempt++) {
            const result = await fn();
            if (result.ok) return result;
            lastError = result.error;
            if (attempt < maxRetries) {
                const delayMs = Math.pow(2, attempt) * 1000;
                logger.warn({ attempt: attempt + 1, delayMs }, `Retry in ${delayMs}ms...`);
                await new Promise(resolve => setTimeout(resolve, delayMs));
            }
        }
        return { ok: false, error: lastError || new Error('Max retries exceeded') };
    }

    public healthCheck(): { online: boolean; details: string } {
        return {
            online: existsSync(this.basePath),
            details: existsSync(this.basePath) ? 'Pipeline substrate verified.' : 'Pipeline output path missing.'
        };
    }
}

import { type Result, type Ternary, type TaskClass, type AICapability, type RoutingSnapshot, type RoutingDecisionAudit } from '../../core/models.js';
import { CapabilityRegistry, type AIServiceType } from './CapabilityRegistry.js';
import { ModelClient } from '../../clients/ModelClient.js';
import { WorkforceManifest } from '../../routing/WorkforceManifest.js';
import { SovereignDomain } from '../../types/SovereignDomain.js';
import { createLogger } from "../../utils/logger.js";
import { SubstrateResolver } from '../../engines/gameplay/SubstrateResolver.js';
import { CNSGodheadPulseVolley } from '../../engines/gameplay/CNSGodheadPulseVolley.js';
import { EventBus } from '../../events/EventBus.js';

const logger = createLogger('AIDispatcher');

export type ServiceState = 'IDLE' | 'CONNECTING' | 'READY' | 'ERROR';

export type ModelTier = "SOVEREIGN_LOCAL" | "ENRICHED_LOCAL" | "CLOUD";

export interface RoutingPolicy {
  primary: ModelTier;
  fallback: ModelTier[];
  allowCloud: boolean;
  cloudOptional: boolean;
}

const MODEL_POLICY: Record<TaskClass, RoutingPolicy> = {
  COMPLETION: {
    primary: "SOVEREIGN_LOCAL",
    fallback: ["ENRICHED_LOCAL", "CLOUD"],
    allowCloud: true,
    cloudOptional: true
  },

  AGENTIC_REASONING: {
    primary: "ENRICHED_LOCAL",
    fallback: ["SOVEREIGN_LOCAL", "CLOUD"],
    allowCloud: true,
    cloudOptional: true
  },

  VISION: {
    primary: "CLOUD",
    fallback: ["ENRICHED_LOCAL"],
    allowCloud: true,
    cloudOptional: false
  },

  RETRIEVAL: {
    primary: "ENRICHED_LOCAL",
    fallback: ["SOVEREIGN_LOCAL"],
    allowCloud: false,
    cloudOptional: true
  },

  CREATIVE_EXPANSION: {
    primary: "CLOUD",
    fallback: ["ENRICHED_LOCAL", "SOVEREIGN_LOCAL"],
    allowCloud: true,
    cloudOptional: true
  }
};

/**
 * AIDispatcher - Autonomous capability selection and execution.
 * Refactored to use unified ModelClient substrate.
 */
export class AIDispatcher {
    private readonly serviceStates: Map<AIServiceType, ServiceState> = new Map();

    constructor(
        private readonly client: ModelClient,
        private readonly workforce: WorkforceManifest
    ) {
        // Initialize service states
        const types: AIServiceType[] = ['GEMINI', 'CLOUDFLARE', 'OLLAMA', 'HUGGINGFACE'];
        types.forEach(t => this.serviceStates.set(t, 'IDLE'));
    }

    async dispatch(request: { capabilityId: string; payload: string; context?: any; snapshot?: RoutingSnapshot; modelOverride?: string }): Promise<Result<any>> {
        const capability = CapabilityRegistry[request.capabilityId];
        if (!capability) {
            return { ok: false, error: new Error(`Capability ${request.capabilityId} not registered.`) };
        }

        const taskClass = capability.taskClass || this.classifyTask(request.capabilityId, request.payload);
        const policy = MODEL_POLICY[taskClass] || MODEL_POLICY.AGENTIC_REASONING;

        // Use provided snapshot or get current from CNS
        const snapshot = request.snapshot || CNSGodheadPulseVolley.getInstance()?.getRoutingSnapshot();

        const modelId = request.modelOverride || this.resolveModelFromPolicy(policy, capability, snapshot);

        const start = Date.now();
        try {
            this.serviceStates.set(capability.serviceType, 'READY');
            const result = await this.client.execute({
                model: modelId,
                prompt: request.payload,
                systemPrompt: `Capability: ${capability.name}\nTask: ${taskClass}\nDomain: ${capability.domain || 'GENERAL'}`
            });

            const latency = Date.now() - start;

            // Causal Routing Audit
            this.auditDecision({
                tick: snapshot?.tick || -1,
                taskClass,
                policy,
                snapshotHash: snapshot ? this.hashSnapshot(snapshot) : 'LIVE',
                selectedModel: modelId,
                selectedTier: this.getTierFromModel(modelId, capability),
                latencyMs: latency,
                success: result.ok
            });

            return result;
        } catch (error) {
            this.serviceStates.set(capability.serviceType, 'ERROR');
            const errorMessage = error instanceof Error ? error.message : String(error);

            if (capability.fallback) {
                logger.warn({ capabilityId: request.capabilityId, fallback: capability.fallback, error: errorMessage }, 'Dispatch exception, attempting fallback');
                return this.dispatch({ ...request, capabilityId: capability.fallback });
            }

            return {
                ok: false,
                error: new Error(errorMessage)
            };
        }
    }

    private classifyTask(id: string, payload: string): TaskClass {
        if (id.includes('vision') || id.includes('eye') || payload.includes('.png')) return "VISION";
        if (id.includes('search') || id.includes('retrieve') || id.includes('atlas')) return "RETRIEVAL";
        if (id.includes('completion') || id.includes('scaffold')) return "COMPLETION";
        if (id.includes('generate') || id.includes('creative')) return "CREATIVE_EXPANSION";
        return "AGENTIC_REASONING";
    }

    private resolveModelFromPolicy(policy: RoutingPolicy, capability: AICapability, snapshot?: RoutingSnapshot): string {
        const rolodex = this.client.getRolodex();

        // 0. Policy-Driven Cloud Gate
        let cloudStatus = 'ONLINE';
        let cloudEffect = 'NONE';

        if (snapshot) {
            cloudStatus = snapshot.cloudHealth.status;
            cloudEffect = snapshot.cloudHealth.effect;
        } else {
            const signal = SubstrateResolver.getCloudSignal();
            cloudStatus = signal.status;
            cloudEffect = signal.effect;
        }

        const forceLocal = !policy.allowCloud || cloudEffect === 'BLOCK_CLOUD_TASKS';

        // 1. Try Primary Tier (if not forced local or primary is already local)
        if (!forceLocal || policy.primary !== 'CLOUD') {
            const primaryModel = this.getModelForTier(policy.primary, capability);
            const isHealthy = snapshot ? snapshot.modelHealthMap[primaryModel] : rolodex?.isModelHealthy(primaryModel);
            if (isHealthy) return primaryModel;
        }

        // 2. Try Fallback Tiers in order
        for (const tier of policy.fallback) {
            if (forceLocal && tier === 'CLOUD') continue;
            const fallbackModel = this.getModelForTier(tier, capability);
            const isHealthy = snapshot ? snapshot.modelHealthMap[fallbackModel] : rolodex?.isModelHealthy(fallbackModel);
            if (isHealthy) return fallbackModel;
        }

        // 3. Absolute Floor: Sovereign Local
        return this.getModelForTier("SOVEREIGN_LOCAL", capability);
    }

    private getModelForTier(tier: ModelTier, capability: AICapability): string {
        switch (tier) {
            case "SOVEREIGN_LOCAL": 
                return this.client.config.masterLocalModel || 'deepseek-r1:8b';
            case "ENRICHED_LOCAL": 
                return this.client.config.localFallbackModel || 'deepseek-r1:8b';
            case "CLOUD": 
                return capability.modelId || this.client.config.orchestratorModel;
        }
    }

    private getTierFromModel(modelId: string, capability: AICapability): ModelTier {
        if (modelId === (this.client.config.masterLocalModel || 'deepseek-r1:8b')) return "SOVEREIGN_LOCAL";
        if (modelId === capability.modelId) return "CLOUD";
        return "ENRICHED_LOCAL";
    }

    private hashSnapshot(snapshot: RoutingSnapshot): string {
        // Simple hash of the snapshot state
        const data = `${snapshot.tick}-${snapshot.cloudHealth.status}-${snapshot.substrateHealth}`;
        return `snap:${snapshot.tick}`;
    }

    private auditDecision(audit: RoutingDecisionAudit): void {
        logger.info({
            tick: audit.tick,
            task: audit.taskClass,
            model: audit.selectedModel,
            snap: audit.snapshotHash,
            tier: audit.selectedTier
        }, '🧬 Cognitive Routing Audit');

        EventBus.getInstance().publish({
            type: 'decision.routing',
            source: 'AIDispatcher',
            payload: {
                ...audit,
                timestamp: new Date().toISOString(),
                sessionId: (globalThis as any).pog2_sessionId || 'unknown'
            }
        });
    }

    public getServiceState(type: AIServiceType): ServiceState {
        return this.serviceStates.get(type) || 'IDLE';
    }

    public healthCheck(): { online: boolean; details: string } {
        const statuses = Array.from(this.serviceStates.entries())
            .map(([type, state]) => `${type}: ${state}`)
            .join(', ');
        return {
            online: true,
            details: `AI Dispatcher ready. Service States: ${statuses}`
        };
    }
}

